head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00008";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00008.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        let errorStr = "";
        const errors = (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).getErrors === 'function' ? (scwin.openerScwin()).getErrors() : void 0), $c.win.closePopup([]));
        for (let i = 0; i < errors.length; i++) {
            errorStr += "<a href=''>" + errors[i].message + "</a><br/>";
        }
        document.write(errorStr);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00008.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
